#!/usr/bin/env python3
"""Offline review of actual synthetic host branch receipts + Core-exported setup.
Not native rendering, model output, human adjudication or safety certification.
Regenerate inputs: see docs/ai/scenario-experience-handoff.md.
"""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
report = json.loads((ROOT/'artifacts/ai/six-hazard/branch-report.json').read_text())
setup = json.loads((ROOT/'fixtures/ai/rehearsal-experience-review.json').read_text())
copy = {}
for domain in ('native','common','scenarios'):
    copy.update(json.loads((ROOT/f'content/locales/en/{domain}.json').read_text()))
def state(value):
    receipt = value['receipt']
    return {k:receipt.get(k) for k in ('snapshot','experience','routes','contextDigest')}
rows = []
for row in report['rows']:
    assert row['status'] == 'passed'
    design = next(run['design'] for run in setup['runs'] if run['design']['scenarioID'] == row['hazard'])
    decisions = []
    for decision in row['decisions']:
        decisions.append(dict(label=decision['label'], before=state(decision['initial']),
            alternatives=[dict(commands=b['commands'],state=state(b['result'])) for b in decision['alternatives']]))
    rows.append(dict(id=row['hazard'], design=design, decisions=decisions))
first = report['rows'][0]['decisions'][0]['initial']['session']['initial']
data = dict(rows=rows,home=first['home'],household=first['household'],copy=copy)
payload = json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
page = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DryRun · Six experiences</title>
<style>
:root{font-family:system-ui,sans-serif;color:#202c32;background:#f5f3ef;font-size:16px}body{margin:0}header,main{max-width:1440px;margin:auto;padding:28px}h1{font-size:clamp(28px,4vw,46px);letter-spacing:-.045em;margin:10px 0}h2{font-size:23px;letter-spacing:-.025em;margin:0}p{line-height:1.5}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.14em;font-weight:700;color:#45666b}.note{max-width:1000px;color:#526067}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,400px),1fr));gap:20px}.card{--accent:#a33020;background:#fff;border-radius:22px;box-shadow:0 3px 18px #1729310b;border:1px solid #dfe4e4;overflow:hidden}.cardhead{padding:22px;border-top:6px solid var(--accent)}.objective{font-size:15px;margin:10px 0 0;color:#526067;min-height:46px}.scene{min-height:255px;padding:16px 22px;background:color-mix(in srgb,var(--accent) 6%,white)}svg{display:block;width:100%;height:220px}.metrics{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}.metric{background:#fff;border:1px solid #dae1e2;border-radius:12px;padding:10px 13px;flex:1}.metric strong{font-size:24px;display:block}.metric span{font-size:12px;color:#56686e}.controls{padding:20px 22px}select{width:100%;font:inherit;border:1px solid #b5c3c7;border-radius:8px;padding:10px;background:white;margin:8px 0 12px}button{font:inherit;min-height:44px;background:white;border:1px solid #c4d0d3;border-radius:8px;padding:8px 13px;cursor:pointer}button[aria-pressed=true]{background:var(--accent);color:white;border-color:var(--accent)}.buttons{display:flex;gap:8px}.action{font-size:14px;min-height:60px;color:#3e555c;line-height:1.45}.range{font-size:45px;font-weight:700;letter-spacing:-.05em;margin:18px 0}.status{font-size:14px;padding:8px 0;display:flex;justify-content:space-between;gap:12px}.status b{font-size:13px}.room{padding:11px 13px;background:#fff;border-radius:9px;margin:7px 0;display:flex;justify-content:space-between;gap:8px}.bar{height:10px;background:#dfe8ed;border-radius:9px;overflow:hidden;margin:6px 0 15px}.fill{height:100%;background:var(--accent)}.tankrow{display:flex;gap:28px;align-items:center;padding:20px 10px}.tank{position:relative;width:78px;height:145px;border:3px solid #237e99;border-radius:12px;overflow:hidden;background:#f6fbfd}.tankfill{position:absolute;bottom:0;width:100%;background:#66b9d4;border-top:3px solid #147390}.caption{font-size:12px;color:#5b6a70}.review{margin-top:14px;border-top:1px solid #e0e5e6;padding-top:12px}summary{cursor:pointer;font-weight:600;padding:8px 0}ul{padding-left:20px}li{font-size:14px;margin:7px 0;line-height:1.4}code{font-size:11px;overflow-wrap:anywhere}footer{max-width:1400px;margin:auto;padding:28px;color:#586c73;font-size:13px}button:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #173b8c;outline-offset:3px}@media(prefers-reduced-motion:no-preference){.card{transition:box-shadow .15s}}@media(prefers-color-scheme:dark){:root{background:#11191d;color:#ecf1f2}.card{background:#1b262b;border-color:#3d4d55}.scene{background:#202e34}.metric,.room,select,button{background:#26363e;color:#edf3f5;border-color:#566973}.objective,.note,.action,.caption,.metric span,footer{color:#b6c8ce}.tank{background:#243c47}.bar{background:#354b56}}
</style><header><div class="eyebrow">DryRun / Scenario experience review</div><h1>One household. Six different problems.</h1><p class="note">Compare actual host consequences using the same synthetic home, people, supplies and recorded alternative. Choose either decision, then compare its starting state and two independently replayed branches.</p><p class="caption">Portable design preview · zero model calls · not an iPhone screenshot · native integration and human safety/language review pending. Setup below uses the private-well household; branch fixtures explicitly use municipal water. Their difference is retained.</p></header><main class="grid" id="grid"></main><footer>Source: artifacts/ai/six-hazard/branch-report.json + fixtures/ai/rehearsal-experience-review.json. Actual command IDs and debrief fact IDs remain inspectable for Claude. Temperature ranges are illustrative host calculations, never measurements, medical limits or predictions of safety.</footer>
<script type="application/json" id="data">PAYLOAD</script><script>
const data=JSON.parse(document.getElementById('data').textContent),C=data.copy,params=new URLSearchParams(location.search);
const colors={'home-fire':'#af3025',tornado:'#7046a5','flash-flood':'#14778a','freeze-power-loss':'#275eaa','heat-grid-strain':'#ad5d10','water-outage':'#117b9a'};
const baseline=(hazard,key)=>data.rows.find(r=>r.id===hazard).decisions[0].before.snapshot.resources[key]?.amount;
const text=k=>C[k]||k, name=id=>data.household.people.find(p=>p.id===id)?.alias||data.home.spaces.find(r=>r.id===id)?.label||id;
function el(tag,content,parent,cls){const n=document.createElement(tag);if(content!==undefined)n.textContent=content;if(cls)n.className=cls;if(parent)parent.append(n);return n}
function metric(parent,label,value){const m=el('div',undefined,parent,'metric');el('strong',value,m);el('span',label,m)}
function service(parent,state,id,label){const r=el('div',undefined,parent,'status');el('span',label,r);el('b',state.snapshot.services[id]||'unknown',r)}
function svgEl(tag,attrs,parent){const n=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);parent.append(n);return n}
function plan(parent,state,id){const svg=svgEl('svg',{viewBox:'-1 -1 18 14',role:'img','aria-label':'Current recorded room layout and modeled routes'},parent);const spatial=state.snapshot.spatialState||{},e=state.experience||{};
const defs=svgEl('defs',{},svg),pattern=svgEl('pattern',{id:'pattern-'+id,width:'.6',height:'.6',patternUnits:'userSpaceOnUse'},defs);svgEl('path',{d:id==='flash-flood'?'M0 .3 Q.15 .1 .3 .3 T.6 .3':'M0 .6 L.6 0',stroke:colors[id],'stroke-width':'.07',fill:'none'},pattern);
for(const room of data.home.spaces){const p=room.polygon,affected=spatial.affectedSpaceIDs?.includes(room.id),shelter=e.shelterRoomID===room.id&&id==='tornado';svgEl('polygon',{points:p.map(p=>`${p.x},${p.y}`).join(' '),fill:affected?'url(#pattern-'+id+')':shelter?'#bfe2d4':'#eef2f3',stroke:'#50646d','stroke-width':'.08'},svg);const x=p.reduce((s,p)=>s+p.x,0)/p.length,y=p.reduce((s,p)=>s+p.y,0)/p.length;svgEl('text',{x,y,'text-anchor':'middle','font-size':'.42',fill:'#263942'},svg).textContent=room.label||room.kind;}
for(const route of state.routes.slice(0,1)){for(const leg of route.primary?.legs||[])svgEl('polyline',{points:leg.points.map(p=>`${p.x},${p.y}`).join(' '),fill:'none',stroke:'#087690','stroke-width':'.13','stroke-linejoin':'round'},svg)}
const metrics=el('div',undefined,parent,'metrics');if(id==='home-fire'){metric(metrics,'Outside',e.outsidePersonIDs.length+'/'+data.household.people.length);metric(metrics,'Accounted outside',e.accountedPersonIDs.length+'/'+data.household.people.length)}else if(id==='tornado'){metric(metrics,'Arrived at shelter',e.shelteredPersonIDs.length+'/'+data.household.people.length);metric(metrics,'Shelter',name(e.shelterRoomID||'Not recorded'))}else{metric(metrics,'Recorded departure',e.relocated?'Used':'Not used');metric(metrics,'Affected rooms',spatial.affectedSpaceIDs?.length||0)}}
function thermal(parent,state,id){const e=state.experience||{},t=e.temperature;el('div',t?`${t.lowerC.toFixed(1)}–${t.upperC.toFixed(1)} °C`:'Range not recorded',parent,'range');el('div','Illustrative exercise range',parent,'caption');service(parent,state,id==='freeze-power-loss'?'svc.heat':'svc.cooling',id==='freeze-power-loss'?'Heating':'Cooling');service(parent,state,'svc.power.home','Home power');if(id==='freeze-power-loss'){for(const[k,v]of Object.entries(state.snapshot.resources).filter(([k])=>k.startsWith('res.backup.'))){el('div',`${k}: ${v.amount??'unknown'} ${v.unit}`,parent,'caption');const bar=el('div',undefined,parent,'bar'),fill=el('div',undefined,bar,'fill');const initial=baseline(id,k);fill.style.width=Number.isFinite(v.amount)&&initial>0?Math.max(0,Math.min(100,v.amount/initial*100))+'%':'0';if(v.amount==null)bar.hidden=true}}else{for(const[k,t]of Object.entries(e.roomTemperatures||{}).slice(0,3)){const r=el('div',undefined,parent,'room');el('span',name(k),r);el('b',`${t.lowerC.toFixed(1)}–${t.upperC.toFixed(1)} °C`,r)}}}
function water(parent,state){const e=state.experience||{},v=state.snapshot.resources['res.water.stored'],initial=baseline('water-outage','res.water.stored');const row=el('div',undefined,parent,'tankrow'),tank=el('div',undefined,row,'tank'),fill=el('div',undefined,tank,'tankfill');fill.style.height=v?.amount==null||!(initial>0)?'0':Math.max(0,Math.min(100,v.amount/initial*100))+'%';const number=el('div',undefined,row);el('div',v?.amount==null?'Not recorded':`${v.amount} ${v.unit}`,number,'range');el('div',`Stored water · ${initial??'unknown'} ${v?.unit??''} fixture baseline`,number,'caption');service(parent,state,'svc.water.supply','Tap service');el('p',text('experience.scene.'+(e.waterAdvisory||'noAdvisory')),parent);el('div','Drinking · Cooking · Hygiene — activity and advisory determine usable supply.',parent,'caption')}
for(const row of data.rows){const card=el('article',undefined,document.getElementById('grid'),'card');card.style.setProperty('--accent',colors[row.id]);const head=el('div',undefined,card,'cardhead');el('h2',text('common.scenario.'+row.id),head);el('p',text(row.design.objectiveKey),head,'objective');const scene=el('div',undefined,card,'scene'),controls=el('div',undefined,card,'controls');el('label','Compare a real decision',controls);const select=el('select',undefined,controls);select.setAttribute('aria-label',row.id+' decision');row.decisions.forEach((d,i)=>{const o=el('option',d.label,select);o.value=i});const buttons=el('div',undefined,controls,'buttons'),action=el('p',undefined,controls,'action'),review=el('details',undefined,controls,'review');el('summary','Readiness setup and debrief',review);for(const q of row.design.questions){el('p',text(q.promptKey),review);const ul=el('ul',undefined,review);q.options.forEach(o=>el('li',text(o.labelKey),ul))}const facts=el('div',undefined,review);select.value=String(Math.min(row.decisions.length-1,Math.max(0,Number(params.get('decision')||0))));let branch=Math.min(1,Math.max(-1,Number(params.get('branch')??-1)));
const bs=['Before','Choice A','Choice B'].map((label,i)=>{const b=el('button',label,buttons);b.onclick=()=>{branch=i-1;render()};return b});function render(){const d=row.decisions[Number(select.value)],s=branch<0?d.before:d.alternatives[branch].state;scene.replaceChildren();if(['home-fire','tornado','flash-flood'].includes(row.id))plan(scene,s,row.id);else if(row.id==='water-outage')water(scene,s);else thermal(scene,s,row.id);bs.forEach((b,i)=>b.setAttribute('aria-pressed',String(branch===i-1)));action.textContent=branch<0?'Actual committed starting state. Select a branch to compare computed effects.':d.alternatives[branch].commands.map(c=>[c.kind,c.target&&name(c.target),c.value&&name(c.value),c.quantityLiters&&`${c.quantityLiters} L`].filter(Boolean).join(' · ')).join(' → ');facts.replaceChildren();el('p',text(row.design.debriefKey),facts);el('div','Host debrief fact IDs for native integration:',facts,'caption');for(const f of s.experience.debrief.slice(0,6))el('p',f.kind+' → '+f.nextActionID,facts,'caption');el('code','Receipt '+s.contextDigest,facts)}select.onchange=()=>{branch=-1;render()};render()}
</script></html>'''
output=ROOT/'artifacts/ai/rehearsal-experience-preview.html'
output.parent.mkdir(parents=True,exist_ok=True)
output.write_text(page.replace('PAYLOAD',payload))
print(output.relative_to(ROOT))
print(f'{len(rows)} hazards; {sum(len(r["decisions"])*2 for r in rows)} computed branches; no network or model calls')
